/**
 * An abstract {@link GhidraScriptProvider} used to provide common functionality to different
 * types of Python script implementations
 */
public abstract class AbstractPythonScriptProvider : GhidraScriptProvider {

	private static readonly Pattern BLOCK_COMMENT = Pattern.compile("'''");

	/* @Override */
	public abstract string getDescription();

	/* @Override */
	public abstract string getRuntimeEnvironmentName();

	/* @Override */
	public abstract GhidraScript getScriptInstance(ResourceFile sourceFile, PrintWriter writer);

	/* @Override */
	public void createNewScript(ResourceFile newScript, string category)
    {
		using (PrintWriter writer = new PrintWriter(new FileWriter(newScript.getFile(false))))
{
			writeHeader(writer, category);
			writer.println("");
			writeBody(writer);
			writer.println("");
		}
	}

	/**
